(()=>{const button=document.getElementById('studio-check'),box=document.getElementById('studio-check-results');function row(name,value,action=''){const card=document.createElement('article');card.className='record';const title=document.createElement('strong'),message=document.createElement('p');title.textContent=name;message.textContent=value+(action?' · '+action:'');card.append(title,message);box.append(card);}async function request(path){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),10000);try{const r=await fetch(path,{signal:controller.signal}),d=await r.json();if(!r.ok)throw Error(d.error||'Service unavailable');return d;}finally{clearTimeout(timeout);}}
button.onclick=async()=>{button.disabled=true;box.replaceChildren();row('Checked at',new Date().toLocaleString());try{row('Secure browser',window.isSecureContext?'Ready':'Unavailable','Camera and microphone access require HTTPS.');row('Camera & microphone API',navigator.mediaDevices?.getUserMedia?'Available — permission still required':'Unavailable','Use a supported browser and allow access when you start a device.');row('Phone pairing',window.RTCPeerConnection?'Supported by this browser':'Unavailable','Phones and Studio must share Wi-Fi; internet relay is not configured.');const formats=window.MediaRecorder?['video/webm;codecs=vp8,opus','video/webm','video/mp4'].filter(t=>MediaRecorder.isTypeSupported(t)):[];row('Video recording',formats.length?'Supported: '+formats.join(', '):'Unavailable','Actual recording still requires a connected camera, screen or media scene.');row('Screen sharing',navigator.mediaDevices?.getDisplayMedia?'API available — choose a screen to confirm':'Unavailable here','Use desktop Chrome or another supported desktop browser.');if(navigator.permissions?.query){for(const name of ['camera','microphone']){try{const p=await navigator.permissions.query({name});row(name==='camera'?'Camera permission':'Microphone permission',p.state==='granted'?'Allowed':p.state==='denied'?'Permission missing':'Ask when starting',p.state==='denied'?'Open this site’s browser permissions and allow access.':'Hardware availability is checked when you connect.');}catch{row(name+' permission','Browser cannot report it','Start the device to request permission.');}}}const checks=await Promise.allSettled([request('/api/studio/jobs'),request('/api/designer/media'),request('/api/studio/campaigns/status')]);checks.forEach((result,i)=>{const name=['Creative jobs','Private files','Platform publishing'][i];if(result.status!=='fulfilled'){row(name,'Source unavailable',result.reason.message==='The user aborted a request.'?'Connection timed out. Try again.':result.reason.message);return;}const d=result.value;if(i===0)row(name,'Connected · '+d.jobs.length+' active jobs returned');if(i===1){const bytes=d.files.reduce((sum,f)=>sum+f.size,0);row(name,'Connected · '+d.files.length+' / 100 files · '+(bytes/1048576).toFixed(1)+' / 1024 MB','Each upload is limited to 50 MB.');}if(i===2){row(name,d.publishing,'Automatic scheduling: '+(d.automaticScheduling?'Available':'Unavailable'));row('AI content provider',d.polsia);}});const state=window.studioConnectionSnapshot?.();if(state){row('Camera session',state.active?'Active until '+new Date(state.expiresAt).toLocaleTimeString():'Not started');row('Connected phones',state.connected+' / 5');}row('Privacy','This check did not activate cameras, record, upload or publish.');}catch(e){row('Studio check','Could not finish',e.message);}finally{button.disabled=false;}};
})();
